func reconstruct(fullPath string, ps Params) string {
	out := ""
	i := 0
	for i < len(fullPath) {
		if fullPath[i] == ':' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			key := fullPath[i+1 : j]
			v, ok := ps.Get(key)
			if !ok {
				return "<missing:" + key + ">"
			}
			out += v
			i = j
		} else if fullPath[i] == '*' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
