// Try to match the next rune of the remaining path against the non-wildcard
// children of n, case-insensitively. Returns nil if no child matched.
func (n *node) findCaseInsensitivePathIndices(oldPath, path string, ciPath []byte, rb [4]byte, fixTrailingSlash bool) []byte {
	npLen := len(n.path)
	rb = shiftNRuneBytes(rb, npLen)

	if rb[0] != 0 {
		idxc := rb[0]
		for i, c := range []byte(n.indices) {
			if c == idxc {
				return n.children[i].findCaseInsensitivePathRec(path, ciPath, rb, fixTrailingSlash)
			}
		}
		return nil
	}

	var rv rune
	var off int
	for max := min(npLen, 3); off < max; off++ {
		if i := npLen - off; utf8.RuneStart(oldPath[i]) {
			rv, _ = utf8.DecodeRuneInString(oldPath[i:])
			break
		}
	}

	lo := unicode.ToLower(rv)
	utf8.EncodeRune(rb[:], lo)
	rb = shiftNRuneBytes(rb, off)

	idxc := rb[0]
	for i, c := range []byte(n.indices) {
		if c == idxc {
			if out := n.children[i].findCaseInsensitivePathRec(path, ciPath, rb, fixTrailingSlash); out != nil {
				return out
			}
			break
		}
	}

	if up := unicode.ToUpper(rv); up != lo {
		utf8.EncodeRune(rb[:], up)
		rb = shiftNRuneBytes(rb, off)

		idxc := rb[0]
		for i, c := range []byte(n.indices) {
			if c == idxc {
				return n.children[i].findCaseInsensitivePathRec(path, ciPath, rb, fixTrailingSlash)
			}
		}
	}
	return nil
}
