var segs = []string{"a", "b", "c", "ab", "abc", "x", "xy", "foo", "bar", "1", "12", "aa", "bb"}

func randPath(r *rand.Rand, maxSeg int) string {
	n := 1 + r.Intn(maxSeg)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segs[r.Intn(len(segs))])
	}
	return "/" + strings.Join(parts, "/")
}

func randRoute(r *rand.Rand, maxSeg int) string {
	n := 1 + r.Intn(maxSeg)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch r.Intn(10) {
		case 0, 1, 2:
			parts = append(parts, ":"+string(rune('p'+i%5)))
		default:
			parts = append(parts, segs[r.Intn(len(segs))])
		}
	}
	p := "/" + strings.Join(parts, "/")
	if r.Intn(8) == 0 {
		p += "/*rest"
	}
	if r.Intn(8) == 0 {
		p += "/"
	}
	return p
}

// reconstruct the request path from fullPath + params
func reconstruct(fullPath string, ps Params) string {
	out := ""
	i := 0
	for i < len(fullPath) {
		if fullPath[i] == ':' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			key := fullPath[i+1 : j]
			v, ok := ps.Get(key)
			if !ok {
				return "<missing:" + key + ">"
			}
			out += v
			i = j
		} else if fullPath[i] == '*' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			key := fullPath[i+1 : j]
			v, ok := ps.Get(key)
			if !ok {
				return "<missing:" + key + ">"
			}
			// catch-all value includes the leading '/', which was already emitted
			out = strings.TrimSuffix(out, "/") + v
			i = j
		} else {
			out += string(fullPath[i])
			i++
		}
	}
	return out
}

