package gin

import (
	"fmt"
	"math/rand"
	"regexp"
	"strings"
	"testing"
)

var words = []string{"a", "b", "c", "ab", "abc", "x", "xy", "foo", "bar", "1", "12", "aa", "bb", "user_", "id", "get", "test", "abc"}

func genSeg(r *rand.Rand, i int) string {
	switch r.Intn(12) {
	case 0, 1, 2, 3:
		return ":" + string(rune('p'+i%4))
	case 4:
		// mid-segment param
		return words[r.Intn(len(words))] + ":" + string(rune('p'+i%4))
	case 5:
		// param then static suffix
		return ":" + string(rune('p'+i%4)) + words[r.Intn(len(words))]
	default:
		return words[r.Intn(len(words))]
	}
}

func genRoute(r *rand.Rand) string {
	n := 1 + r.Intn(4)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, genSeg(r, i))
	}
	p := "/" + strings.Join(parts, "/")
	if r.Intn(6) == 0 {
		p += "/*rest"
	} else if r.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func genPath(r *rand.Rand) string {
	n := 1 + r.Intn(5)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, words[r.Intn(len(words))])
	}
	return "/" + strings.Join(parts, "/")
}

// routeToRegex converts a gin route pattern into a regexp with named groups.
func routeToRegex(route string) (*regexp.Regexp, []string) {
	var names []string
	var sb strings.Builder
	sb.WriteString("^")
	i := 0
	for i < len(route) {
		c := route[i]
		if c == ':' || c == '*' {
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			name := route[i+1 : j]
			names = append(names, name)
			if c == '*' {
				// the '/' preceding the catch-all belongs to the captured value
				cur := sb.String()
				if strings.HasSuffix(cur, "/") {
					sb.Reset()
					sb.WriteString(strings.TrimSuffix(cur, "/"))
				}
				sb.WriteString("(/.*)")
			} else {
				sb.WriteString("([^/]*)")
			}
			i = j
			continue
		}
		sb.WriteString(regexp.QuoteMeta(string(c)))
		i++
	}
	sb.WriteString("$")
	re, err := regexp.Compile(sb.String())
	if err != nil {
		return nil, nil
	}
	return re, names
}

func TestZZRef(t *testing.T) {
	r := rand.New(rand.NewSource(7))
