			}()
			if ok {
				routes = append(routes, rt)
			}
		}
		if len(routes) == 0 {
			continue
		}
		for k := 0; k < 30; k++ {
			p := genPath(r)
			params := make(Params, 0, 20)
			sn := make([]skippedNode, 0, 20)
			v := tree.getValue(p, &params, &sn, false)

			// reference: which routes match?
			var matching []string
			for _, rt := range routes {
				re, _ := routeToRegex(rt)
				if re != nil && re.MatchString(p) {
					matching = append(matching, rt)
				}
			}
			if v.handlers == nil {
				if len(matching) > 0 {
					miss++
					if miss <= 10 {
						fmt.Printf("MISS path=%q routes=%v matching=%v\n", p, routes, matching)
					}
				}
				continue
			}
			// matched: check fullPath is among matching
			found := false
			for _, m := range matching {
				if m == v.fullPath {
					found = true
				}
			}
			if !found {
				wrong++
				if wrong <= 10 {
					fmt.Printf("WRONG path=%q fullPath=%q routes=%v matching=%v\n", p, v.fullPath, routes, matching)
				}
			}
			if v.params == nil {
				continue
			}
			for _, pr := range *v.params {
				if pr.Value == "" {
					empty++
					if empty <= 10 {
						fmt.Printf("EMPTY path=%q fullPath=%q params=%v routes=%v\n", p, v.fullPath, *v.params, routes)
					}
				}
			}
		}
	}
	fmt.Println("miss:", miss, "wrong:", wrong, "empty:", empty)
}

